DROP TABLE PBC_SPE_COUNTER_PARTY;
CREATE TABLE PBC_SPE_COUNTER_PARTY (
    PBC_UUID VARCHAR2(64) NOT NULL,
    PARTY_ORG_CODE VARCHAR2(200),
    PARTY_ORG_NAME VARCHAR2(120),
    PARTY_PROD_ID VARCHAR2(15),
    PARTY_PROD_NAME VARCHAR2(50),
    PARTY_PROD_TYPE VARCHAR2(1),
    ASSET_CODE VARCHAR2(50) NOT NULL,
    ASSET_TYPE VARCHAR2(5),
    STATUS VARCHAR2(2),
    CREATE_USER VARCHAR2(20),
    CREATE_DEPT VARCHAR2(20),
    CREATE_TIME TIMESTAMP(6),
    UPDATE_USER VARCHAR2(20),
    UPDATE_TIME TIMESTAMP(6),
    CONSTRAINT PK_PBC_SPE_COUNTER_PARTY PRIMARY KEY (PBC_UUID)
);
COMMENT ON TABLE PBC_SPE_COUNTER_PARTY IS '特定目的载体对手方信息维护表';
COMMENT ON COLUMN PBC_SPE_COUNTER_PARTY.PBC_UUID IS 'UUID';
COMMENT ON COLUMN PBC_SPE_COUNTER_PARTY.PARTY_ORG_CODE IS '交易对手机构编码';
COMMENT ON COLUMN PBC_SPE_COUNTER_PARTY.PARTY_ORG_NAME IS '交易对手机构名称';
COMMENT ON COLUMN PBC_SPE_COUNTER_PARTY.PARTY_PROD_ID IS '交易对手产品代码';
COMMENT ON COLUMN PBC_SPE_COUNTER_PARTY.PARTY_PROD_NAME IS '交易对手产品名称';
COMMENT ON COLUMN PBC_SPE_COUNTER_PARTY.PARTY_PROD_TYPE IS '交易对手产品种类';
COMMENT ON COLUMN PBC_SPE_COUNTER_PARTY.ASSET_CODE IS '资产代码';
COMMENT ON COLUMN PBC_SPE_COUNTER_PARTY.ASSET_TYPE IS '资产负债项目';
COMMENT ON COLUMN PBC_SPE_COUNTER_PARTY.STATUS IS '数据状态: A：待处理 D：删除 E：有效 M：修改';
COMMENT ON COLUMN PBC_SPE_COUNTER_PARTY.CREATE_USER IS '创建人';
COMMENT ON COLUMN PBC_SPE_COUNTER_PARTY.CREATE_DEPT IS '创建部门';
COMMENT ON COLUMN PBC_SPE_COUNTER_PARTY.CREATE_TIME IS '创建时间';
COMMENT ON COLUMN PBC_SPE_COUNTER_PARTY.UPDATE_USER IS '更新人';
COMMENT ON COLUMN PBC_SPE_COUNTER_PARTY.UPDATE_TIME IS '更新时间';

